/* Titres et descriptions : la première variante qui tient dans 50-60 / 150-160 caractères. */
const fit = (xs: string[], min: number, max: number) => xs.find((x) => x.length >= min && x.length <= max) ?? xs[0];
const titleDe = (n: string) => fit([`Einbürgerungstest ${n} 2026: alle 10 Landesfragen gelöst`, `Einbürgerungstest ${n} 2026: 10 Landesfragen mit Lösung`, `Einbürgerungstest ${n} 2026: Landesfragen mit Lösung`, `Einbürgerungstest ${n} 2026: die 10 Landesfragen`, `Einbürgerungstest ${n} 2026: Landesfragen`, `Einbürgerungstest ${n} 2026`], 50, 60);
const titleEn = (n: string) => fit([`Citizenship Test ${n} 2026: All 10 State Questions Answered`, `Citizenship Test ${n} 2026: 10 State Questions, Answers`, `Citizenship Test ${n} 2026: the 10 State Questions`, `Citizenship Test ${n} 2026: State Questions`, `Citizenship Test ${n} 2026: Answers`, `Citizenship Test ${n} 2026`], 50, 60);
/* Description : la base, puis la combinaison d'ajouts (dans l'ordre) qui tombe dans 150-160 caractères. */
function fitParts(base: string, extras: string[], end: string) {
  let best = base + end;
  for (let m = 0; m < 1 << extras.length; m++) {
    const x = base + extras.filter((_, i) => m & (1 << i)).join('') + end;
    if (x.length >= 150 && x.length <= 160) return x;
    if (Math.abs(x.length - 155) < Math.abs(best.length - 155)) best = x;
  }
  return best;
}
const descDe = (n: string, hs: string) => fitParts(`Einbürgerungstest ${n} 2026: die 10 Landesfragen mit Lösung, Hauptstadt ${hs}`, [', Wappen in Worten erklärt', ', Flagge und Wahlalter', ', dazu eine Probeprüfung mit 33 Fragen', ' wie im echten Test', ', kostenlos und ohne Konto'], '.');
const descEn = (n: string, hs: string) => fitParts(`Citizenship test ${n} 2026: the 10 state questions with answers, capital ${hs}`, [', English translation', ', coat of arms explained', ', flag and voting age', ', plus a 33-question mock exam', ' like the real one', ', free, no account'], '.');

